"use strict";
const state={me:null,csrf:null,page:"dashboard"};
const pages=[
 ["dashboard","Dashboard","Visão geral e conexões do DACHBYTE Price"],["orders","Pedidos","Pedidos importados da Tray e vínculo com marketplaces"],["commissions","Comissões","Tabela informativa e ajustável de taxas por canal"],["integrations","Integrações","OAuth e saúde das conexões"],["users","Usuarios","Usuarios, perfis e acessos"],["products","Produtos","Catálogo e rentabilidade por SKU"],["profit","Profit","Margem de contribuição por pedido e produto"],["pricing","Pricing","Decisões recomendadas de preço"],["market","Market","Concorrência e posicionamento"],["ads","Ads","Rentabilidade pós-mídia"],["cash","Cash","Fluxo de caixa e recebíveis"],["audit","Audit","Divergências financeiras e operacionais"],["actions","Actions","Histórico de decisões e resultados"],["reports","Reports & Forecast","Relatórios e previsões"]
];
const $=s=>document.querySelector(s);const el=(tag,attrs={},html="")=>{const n=document.createElement(tag);Object.entries(attrs).forEach(([k,v])=>k==="class"?n.className=v:n.setAttribute(k,v));n.innerHTML=html;return n;};
function toast(msg,error=false){const t=el("div",{class:`toast${error?" error":""}`},escapeHtml(msg));$("#toast").append(t);setTimeout(()=>t.remove(),5000)}
function escapeHtml(s){return String(s??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[m]));}
async function api(path,opts={}){const headers={"Content-Type":"application/json",...(opts.headers||{})};if(state.csrf&&!['GET','HEAD'].includes(String(opts.method||"GET").toUpperCase()))headers["X-CSRF-Token"]=state.csrf;const r=await fetch(`/volt-price/api${path}`,{credentials:"same-origin",...opts,headers});const text=await r.text();let data={};try{data=text?JSON.parse(text):{};}catch{data={message:text}}if(!r.ok){const e=new Error(data.message||data.error||`HTTP ${r.status}`);e.data=data;e.status=r.status;throw e}return data;}
async function hydrateCsrf(){try{state.csrf=(await api("/auth/csrf")).csrfToken;}catch{state.csrf=null;}}
function setFormError(id,message=""){const node=$(id);node.textContent=message;node.classList.toggle("hidden",!message);}
function showLogin(){$("#appView").classList.add("hidden");$("#loginView").classList.remove("hidden");$("#loginForm").classList.remove("hidden");$("#passwordChangeForm").classList.add("hidden");setFormError("#loginError");setFormError("#passwordChangeError");}
async function showFirstAccess(){$("#appView").classList.add("hidden");$("#loginView").classList.remove("hidden");$("#loginForm").classList.add("hidden");$("#passwordChangeForm").classList.remove("hidden");setFormError("#loginError");setFormError("#passwordChangeError");await hydrateCsrf();$("#currentPassword").focus();}
function showApp(){$("#loginView").classList.add("hidden");$("#appView").classList.remove("hidden");renderNav();$("#tenantName").textContent=state.me.tenantName|| (state.me.isPlatformAdmin?"Admin Master":"DACHBYTE Price");$("#userName").textContent=`${state.me.fullName||state.me.email} · ${state.me.role}`;$("#supportBadge").classList.toggle("hidden",!state.me.supportReason);}
function renderNav(){const nav=$("#nav");nav.innerHTML="";pages.forEach(([id,name])=>{const b=el("button",{class:`nav-btn ${state.page===id?"active":""}`,"data-page":id},`<span>${escapeHtml(name)}</span>`);b.onclick=()=>navigate(id);nav.append(b)});if(state.me?.isPlatformAdmin){const b=el("button",{class:`nav-btn ${state.page==="admin"?"active":""}`},"<span>Admin Master</span>");b.onclick=()=>navigate("admin");nav.append(b)}}
async function boot(){try{state.me=(await api("/auth/me")).user;if(state.me.passwordChangeRequired)return showFirstAccess();await hydrateCsrf();showApp();const route=location.pathname.split("/").pop();state.page=pages.some(p=>p[0]===route)||route==="admin"?route:"dashboard";await render();}catch{showLogin();}}
async function navigate(page){state.page=page;history.pushState({},"",`/volt-price/app/${page}`);renderNav();await render();}
function setTitle(title,sub){$("#pageTitle").textContent=title;$("#pageSubtitle").textContent=sub||""}
function money(v){return new Intl.NumberFormat("pt-BR",{style:"currency",currency:"BRL"}).format(Number(v||0))}
function date(v){if(!v)return"—";const d=new Date(v);return Number.isNaN(d)?String(v):d.toLocaleString("pt-BR")}
async function render(){const p=pages.find(x=>x[0]===state.page);setTitle(p?.[1]||(state.page==="admin"?"Admin Master":"DACHBYTE Price"),p?.[2]||"Gestão da plataforma");const root=$("#content");root.innerHTML='<div class="empty">Carregando...</div>';try{if(state.page==="dashboard")return dashboard(root);if(state.page==="orders")return orders(root);if(state.page==="commissions")return commissions(root);if(state.page==="integrations")return integrations(root);if(state.page==="admin")return admin(root);if(state.page==="users")return users(root);return modulePage(root,state.page);}catch(e){root.innerHTML=`<div class="empty danger-note">${escapeHtml(e.message)}</div>`}}
async function dashboard(root){const d=await api("/dashboard/");root.innerHTML=`<div class="pagehead"><div><h1>Dashboard</h1><div class="sub">Centro de decisões financeiras e operacionais</div></div></div><div class="grid kpis"><div class="card kpi"><small>Integrações ativas</small><strong>${d.integrations}</strong></div><div class="card kpi"><small>Pedidos Tray</small><strong>${d.orders}</strong></div><div class="card kpi"><small>Consultas de taxas</small><strong>${d.fees}</strong></div><div class="card kpi"><small>Referências de comissão</small><strong>${d.commissionReferences}</strong></div></div><div class="grid two"><section class="card section"><h3>Fluxo de dados</h3><div class="metric-row"><span>1. Conecte a Tray e importe o período desejado.</span><span class="chip">Importação manual</span></div><div class="metric-row"><span>2. Abra o pedido e identifique o número do marketplace.</span><span class="chip blue">Conciliação</span></div><div class="metric-row"><span>3. Consulte as taxas reais no Mercado Livre ou Shopee.</span><span class="chip green">Taxas reais</span></div></section><section class="card section"><h3>Última sincronização</h3><strong>${date(d.lastSync)}</strong><p class="muted">O refresh de access tokens é automático e não exige reconexão enquanto o refresh token permanecer válido.</p></section></div>`}
async function integrations(root){const data=await api("/integrations/");const connections=data.connections||[];const by=Object.groupBy?Object.groupBy(connections,x=>x.channel):connections.reduce((a,x)=>((a[x.channel]??=[]).push(x),a),{});const emptyIntegration='<p class="muted">Nenhuma conexão ativa. Conecte um canal quando estiver pronto.</p>';root.innerHTML=`<div class="pagehead"><div><h1>Integrações</h1><div class="sub">Canais conectados e saúde dos acessos</div></div></div><div class="grid two"><section class="card section"><div class="section-title"><h3>Integrações</h3><span class="chip">OAuth</span></div><div id="integrationList">${connections.length?"":emptyIntegration}</div></section><section class="card section"><div class="section-title"><h3>Conectar novo canal</h3></div><div class="form-grid"><label class="wide">URL da loja<input id="trayHost" placeholder="https://sualoja.com.br" /></label></div><div class="toolbar"><button class="primary" id="connectTray">Conectar Tray</button><button class="primary" id="connectMeli">Conectar Mercado Livre</button><button class="primary" id="connectShopee">Conectar Shopee</button></div><p class="tiny">Os tokens são armazenados criptografados no banco e renovados automaticamente.</p></section></div>`;const list=$("#integrationList");const statusClasses={connected:"green",expiring:"amber",reauthorization_required:"amber",error:"red",revoked:"red",disconnected:"blue"};for(const channel of ["tray","meli","shopee"]){const conn=(by[channel]||[])[0];const names={tray:"Tray",meli:"Mercado Livre",shopee:"Shopee"};const status=statusClasses[conn?.connection_status]||"blue";const detail=conn?`${escapeHtml(conn.display_name)} · token até ${date(conn.token_expires_at)}`:"Não conectado";const actions=conn?`<span class="chip ${status}">${escapeHtml(conn.connection_status)}</span> <button data-refresh="${channel}">Renovar agora</button> <button class="danger" data-disconnect="${channel}">Desconectar</button>`:'<span class="chip amber">Pendente</span>';const row=el("div",{class:"metric-row integration"},`<div class="logo" aria-hidden="true">${names[channel][0]}</div><div><strong>${names[channel]}</strong><div class="muted">${detail}</div>${conn?.last_error?`<div class="muted">${escapeHtml(conn.last_error)}</div>`:""}</div><div>${actions}</div>`);list.append(row)}
 $("#connectTray").onclick=async()=>connectUrl("/integrations/tray/connect",{storeHost:$("#trayHost").value});$("#connectMeli").onclick=()=>connectUrl("/integrations/meli/connect");$("#connectShopee").onclick=()=>connectUrl("/integrations/shopee/connect");root.querySelectorAll("[data-refresh]").forEach(b=>b.onclick=async()=>{try{await api(`/integrations/${b.dataset.refresh}/refresh`,{method:"POST",body:"{}"});toast("Token renovado.");integrations(root)}catch(e){toast(e.message,true)}});root.querySelectorAll("[data-disconnect]").forEach(b=>b.onclick=async()=>{if(!confirm("Desconectar este canal?"))return;try{await api(`/integrations/${b.dataset.disconnect}/disconnect`,{method:"POST",body:"{}"});toast("Canal desconectado.");integrations(root)}catch(e){toast(e.message,true)}})}
async function connectUrl(path,body={}){try{const d=await api(path,{method:"POST",body:JSON.stringify(body)});location.href=d.authorizationUrl;}catch(e){toast(e.message,true)}}
async function orders(root){const integrationData=await api("/integrations/");const shopeeConnections=(integrationData.connections||[]).filter(connection=>connection.channel==="shopee");const shopeeOptions=shopeeConnections.map(connection=>`<option value="${escapeHtml(connection.id)}">${escapeHtml(connection.display_name||"Shopee")} · loja ${escapeHtml(connection.external_account_id||"—")}</option>`).join("");const noRows='<tr><td colspan="7" class="muted">Nenhum pedido importado para os filtros informados.</td></tr>';root.innerHTML=`<div class="pagehead"><div><h1>Pedidos</h1><div class="sub">Pedidos importados da Tray e vínculo com marketplaces</div></div></div><section class="card section"><div class="toolbar"><label>Status<input class="filter" id="orderStatus" placeholder="A ENVIAR" /></label><label>De<input class="filter" id="orderFrom" type="date" /></label><label>Até<input class="filter" id="orderTo" type="date" /></label><button class="primary" id="syncTray">Sincronizar Tray</button><label>Loja Shopee<select class="filter" id="syncShopeeConnection" ${shopeeConnections.length?"":"disabled"}><option value="">${shopeeConnections.length?"Selecione uma loja":"Nenhuma loja Shopee conectada"}</option>${shopeeOptions}</select></label><button class="primary" id="syncShopee" ${shopeeConnections.length?"":"disabled title=\"Conecte uma loja Shopee em Integrações\""}>Sincronizar Shopee</button><button id="filterOrders">Filtrar local</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Data</th><th>Pedido Tray</th><th>Status</th><th>Total</th><th>Marketplace</th><th>Pedido Marketplace</th><th>Ações</th></tr></thead><tbody id="orderRows"></tbody></table></div></section><div id="feeResult" style="margin-top:16px"></div>`;async function load(){const q=new URLSearchParams();if($("#orderStatus").value)q.set("status",$("#orderStatus").value);if($("#orderFrom").value)q.set("from",$("#orderFrom").value);if($("#orderTo").value)q.set("to",$("#orderTo").value);const d=await api(`/orders/?${q}`);$("#orderRows").innerHTML=d.rows.map(o=>`<tr><td>${escapeHtml(o.order_date||"—")}</td><td>${escapeHtml(o.source_order_id)}</td><td><span class="chip">${escapeHtml(o.status||"—")}</span></td><td>${money(o.total_amount)}</td><td>${escapeHtml(o.marketplace==="meli"?"Mercado Livre":o.marketplace==="shopee"?"Shopee / loja":o.marketplace||"—")}${["meli","shopee"].includes(o.marketplace)?(o.marketplace_account_id?` / ${o.marketplace==="shopee"?"loja":"conta"} ${escapeHtml(o.marketplace_account_id)}`:" / conta nao identificada"):""}</td><td>${escapeHtml(o.marketplace_order_id||"—")}</td><td><button data-hydrate="${o.id}">Detalhar Tray</button> <button data-link="${o.id}" data-current-market="${escapeHtml(o.marketplace||"")}" data-current-order="${escapeHtml(o.marketplace_order_id||"")}">Vincular</button> <button data-profit="${o.id}">Calcular MC</button>${o.marketplace==="meli"&&o.marketplace_order_id&&o.marketplace_account_id?` <button data-fee-meli="${o.id}">Taxas ML</button>`:o.marketplace==="meli"?" <span class=\"muted\">conta nao identificada. Vincule uma conta Mercado Livre para consultar taxas.</span>":""}${o.marketplace==="shopee"&&o.marketplace_order_id?` <button data-fee-shopee="${o.id}">Taxas Shopee</button>`:""}</td></tr>`).join("")||noRows;$("#orderRows").querySelectorAll("[data-hydrate]").forEach(b=>b.onclick=async()=>{try{await api(`/orders/${b.dataset.hydrate}/hydrate-tray`,{method:"POST",body:"{}"});toast("Detalhes atualizados.");load()}catch(e){toast(e.message,true)}});$("#orderRows").querySelectorAll("[data-link]").forEach(b=>b.onclick=async()=>{const marketplace=prompt("Marketplace: meli ou shopee",b.dataset.currentMarket||"meli");if(!marketplace)return;const externalOrderId=prompt("ID do pedido no marketplace",b.dataset.currentOrder||"");if(!externalOrderId)return;const marketplaceAccountId=["meli","shopee"].includes(marketplace)?prompt(marketplace==="shopee"?"ID da loja Shopee":"ID da conta Mercado Livre",""):null;if(["meli","shopee"].includes(marketplace)&&!marketplaceAccountId)return;if(marketplace==="shopee"&&!shopeeConnections.some(connection=>String(connection.external_account_id)===String(marketplaceAccountId)))return toast("Selecione uma loja Shopee conectada para vincular o pedido.",true);try{await api(`/orders/${b.dataset.link}/link-marketplace`,{method:"PATCH",body:JSON.stringify({marketplace,externalOrderId,marketplaceAccountId})});toast("Pedido vinculado.");load()}catch(e){toast(e.message,true)}});$("#orderRows").querySelectorAll("[data-profit]").forEach(b=>b.onclick=async()=>{const costAmount=prompt("CMV/custo do pedido (R$)","0");if(costAmount===null)return;const shippingAmount=prompt("Frete suportado pelo vendedor (R$)","0");if(shippingAmount===null)return;const adsAmount=prompt("Ads atribuído ao pedido (R$)","0");if(adsAmount===null)return;const taxAmount=prompt("Impostos do pedido (R$)","0");if(taxAmount===null)return;try{const d=await api(`/profit/order/${b.dataset.profit}/calculate`,{method:"POST",body:JSON.stringify({costAmount,shippingAmount,adsAmount,taxAmount})});toast(`MC registrada: ${money(d.snapshot.contribution_amount)}`)}catch(e){toast(e.message,true)}});$("#orderRows").querySelectorAll("[data-fee-meli]").forEach(b=>b.onclick=()=>feeMeli(b.dataset.feeMeli));$("#orderRows").querySelectorAll("[data-fee-shopee]").forEach(b=>b.onclick=()=>feeShopee(b.dataset.feeShopee));}
 async function fee(ch,id){try{const d=await api(`/orders/fees/${ch}/${encodeURIComponent(id)}`,{method:"POST",body:"{}"});$("#feeResult").innerHTML=`<section class="card section"><h3>Taxas ${ch==="meli"?"Mercado Livre":"Shopee"} · ${escapeHtml(id)}</h3><div class="grid kpis">${Object.entries(d.summary||{}).slice(0,4).map(([k,v])=>`<div class="card kpi"><small>${escapeHtml(k)}</small><strong>${money(v)}</strong></div>`).join("")}</div><details><summary>Resposta técnica</summary><pre class="fee-json">${escapeHtml(JSON.stringify(d,null,2))}</pre></details></section>`}catch(e){toast(e.message,true)}}
 $("#syncTray").onclick=async()=>{try{const body={status:$("#orderStatus").value||null,from:$("#orderFrom").value||null,to:$("#orderTo").value||null};const d=await api("/orders/sync/tray",{method:"POST",body:JSON.stringify(body)});toast(`${d.totalSynced} pedidos sincronizados em ${d.pages} página(s).`);load()}catch(e){toast(e.message,true)}};$("#syncShopee").onclick=async()=>{const connectionId=$("#syncShopeeConnection").value;if(!connectionId)return toast("Selecione uma loja Shopee para sincronizar.",true);try{const body={connectionId,from:$("#orderFrom").value||null,to:$("#orderTo").value||null};const d=await api("/orders/sync/shopee",{method:"POST",body:JSON.stringify(body)});toast(`${d.totalSynced} pedidos Shopee sincronizados em ${d.pages} página(s).`);load()}catch(e){toast(e.message,true)}};$("#filterOrders").onclick=load;await load();}
async function feeMeli(orderId){return fee("meli",orderId)}
async function feeShopee(orderId){return fee("shopee",orderId)}
async function commissions(root){const d=await api("/commissions/");const commissions=d.commissions||[];const rows=items=>items.map(c=>`<tr><td><strong>${escapeHtml(c.marketplace)}</strong></td><td>${escapeHtml(c.category||"Geral")}</td><td>${escapeHtml(c.title)}</td><td>${c.commission_percent_min==null?"Variável":`${c.commission_percent_min}%${c.commission_percent_max!=c.commission_percent_min?` a ${c.commission_percent_max}%`:""}`}</td><td>${c.fixed_fee==null?"—":money(c.fixed_fee)}</td><td>${escapeHtml((c.extra_fees||[]).map(x=>x.name).join(", ")||"—")}</td><td>${escapeHtml(c.last_verified_at||"—")}</td><td><span class="chip ${c.status==="current"?"green":"amber"}">${escapeHtml(c.status)}</span></td></tr>`).join("")||'<tr><td colspan="8" class="muted">Nenhuma referência de comissão cadastrada.</td></tr>';root.innerHTML=`<div class="pagehead"><div><h1>Comissões</h1><div class="sub">Tabela informativa e ajustável de taxas por canal</div></div><button class="primary" id="newCommission">+ Adicionar referência</button></div><div class="banner-ai"><h4>Referências informativas</h4><p>Esta tabela é somente informativa. Ela não alimenta cálculos de Profit ou Pricing.</p></div><section class="card section" style="margin-top:12px"><div class="toolbar"><label>Canal<select class="filter" id="commissionChannel"><option value="">Todos os canais</option>${[...new Set(commissions.map(c=>c.marketplace))].map(channel=>`<option value="${escapeHtml(channel)}">${escapeHtml(channel)}</option>`).join("")}</select></label><label>Buscar<input class="filter" id="commissionSearch" placeholder="Categoria ou regra" /></label></div><div class="table-wrap"><table class="table"><thead><tr><th>Canal</th><th>Categoria</th><th>Regra</th><th>Comissão</th><th>Taxa fixa</th><th>Extras</th><th>Verificado</th><th>Status</th></tr></thead><tbody id="commissionRows">${rows(commissions)}</tbody></table></div></section><div id="commissionForm"></div>`;const filter=()=>{const channel=$("#commissionChannel").value;const search=$("#commissionSearch").value.trim().toLocaleLowerCase("pt-BR");$("#commissionRows").innerHTML=rows(commissions.filter(c=>(!channel||c.marketplace===channel)&&(!search||`${c.category||""} ${c.title||""}`.toLocaleLowerCase("pt-BR").includes(search))))};$("#commissionChannel").onchange=filter;$("#commissionSearch").oninput=filter;$("#newCommission").onclick=()=>{$("#commissionForm").innerHTML=`<section class="card section" style="margin-top:16px"><h3>Nova referência</h3><div class="form-grid"><label>Marketplace<input id="cMarket" required /></label><label>Categoria<input id="cCategory" /></label><label class="wide">Título/regra<input id="cTitle" required /></label><label>Comissão mín. %<input id="cMin" type="number" step=".01" /></label><label>Comissão máx. %<input id="cMax" type="number" step=".01" /></label><label>Taxa fixa R$<input id="cFixed" type="number" step=".01" /></label><label>Vigência<input id="cFrom" type="date" /></label><label class="wide">Observações<textarea id="cNotes"></textarea></label></div><button class="primary" id="saveCommission">Salvar</button></section>`;$("#saveCommission").onclick=async()=>{try{await api("/commissions/",{method:"POST",body:JSON.stringify({marketplace:$("#cMarket").value,category:$("#cCategory").value,title:$("#cTitle").value,commissionPercentMin:$("#cMin").value||null,commissionPercentMax:$("#cMax").value||null,fixedFee:$("#cFixed").value||null,validFrom:$("#cFrom").value||null,notes:$("#cNotes").value,extraFees:[]})});toast("Referência salva.");commissions(root)}catch(e){toast(e.message,true)}}}}
async function admin(root){if(!state.me.isPlatformAdmin)return root.innerHTML='<div class="empty">Sem acesso.</div>';const [t,a]=await Promise.all([api("/admin/tenants"),api("/admin/audit?limit=50")]);root.innerHTML=`${state.me.tenantId?`<div class="notice">Você está dentro de um tenant em acesso assistido. <button id="exitSupport">Sair do tenant</button></div>`:""}<div class="grid two" style="margin-top:16px"><div class="card"><h3>Empresas</h3><div class="table-wrap"><table><thead><tr><th>Empresa</th><th>Status</th><th>Usuários</th><th></th></tr></thead><tbody>${t.tenants.map(x=>`<tr><td><strong>${escapeHtml(x.name)}</strong><br><small>${escapeHtml(x.slug)}</small></td><td>${escapeHtml(x.status)}</td><td>${x.users_count}</td><td><button data-support="${x.id}">Acessar</button></td></tr>`).join("")}</tbody></table></div></div><div class="card"><h3>Criar tenant</h3><div class="form-grid"><label>Empresa<input id="tName" /></label><label>Slug<input id="tSlug" /></label><label>Owner<input id="tOwner" /></label><label>Email<input id="tEmail" type="email" /></label><label class="wide">Senha inicial<input id="tPass" type="password" /></label></div><button class="primary" id="createTenant">Criar empresa</button></div></div><div class="section-title"><h2>Auditoria recente</h2></div><div class="table-wrap"><table><thead><tr><th>Data</th><th>Ator</th><th>Empresa</th><th>Ação</th><th>Recurso</th></tr></thead><tbody>${a.logs.map(l=>`<tr><td>${date(l.created_at)}</td><td>${escapeHtml(l.actor_email||l.actor_type)}</td><td>${escapeHtml(l.tenant_name||"Plataforma")}</td><td>${escapeHtml(l.action)}</td><td>${escapeHtml(l.resource_type||"")} ${escapeHtml(l.resource_id||"")}</td></tr>`).join("")}</tbody></table></div>`;$("#createTenant").onclick=async()=>{try{await api("/admin/tenants",{method:"POST",body:JSON.stringify({name:$("#tName").value,slug:$("#tSlug").value,ownerName:$("#tOwner").value,ownerEmail:$("#tEmail").value,ownerPassword:$("#tPass").value})});toast("Empresa criada.");admin(root)}catch(e){toast(e.message,true)}};root.querySelectorAll("[data-support]").forEach(b=>b.onclick=async()=>{const reason=prompt("Motivo do acesso assistido:");if(!reason)return;try{const d=await api(`/admin/tenants/${b.dataset.support}/support-session`,{method:"POST",body:JSON.stringify({reason})});state.csrf=d.csrfToken;state.me=(await api("/auth/me")).user;showApp();navigate("dashboard")}catch(e){toast(e.message,true)}});if($("#exitSupport"))$("#exitSupport").onclick=async()=>{try{const d=await api("/admin/exit-support",{method:"POST",body:"{}"});state.csrf=d.csrfToken;state.me=(await api("/auth/me")).user;showApp();navigate("admin")}catch(e){toast(e.message,true)}}}
async function masterTenantUsers(root,tenant){
 const data=await api(`/admin/tenants/${tenant.id}/users`);
 const roles=[["admin","Administrador"],["finance","Financeiro"],["pricing","Pricing"],["marketing","Marketing"],["analyst","Analista"],["viewer","Visualizador"]];
 let resetUser=null;
 const render=()=>{
  root.innerHTML=`<div class="pagehead"><div><h1>Usuários de ${escapeHtml(data.tenant.name)}</h1><div class="sub">Crie acessos e entregue a senha temporária ao usuário por um canal seguro.</div></div><button id="backToTenants">← Empresas</button></div><div class="grid two"><section class="card section"><div class="section-title"><h2>Usuários vinculados</h2><span class="chip">${data.users.length} acesso(s)</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Nome</th><th>Perfil</th><th>Status</th><th>Ação</th></tr></thead><tbody>${data.users.map(user=>`<tr><td><strong>${escapeHtml(user.fullName)}</strong><br><small>${escapeHtml(user.email)}</small>${user.mustChangePassword?'<br><span class="chip amber">Troca de senha pendente</span>':''}</td><td><span class="chip blue">${escapeHtml(roles.find(([role])=>role===user.role)?.[1]||user.role)}</span></td><td><span class="chip ${user.status==="active"?"green":"red"}">${escapeHtml(user.status)}</span></td><td>${roles.some(([role])=>role===user.role)?`<button data-reset-user="${user.id}">Redefinir senha</button>`:'<small class="muted">Owner</small>'}</td></tr>`).join("")||'<tr><td colspan="4" class="muted">Nenhum usuário vinculado.</td></tr>'}</tbody></table></div></section><section class="card section"><div class="section-title"><h2 id="masterUserMode">Novo usuário</h2><span class="chip amber">Senha temporária</span></div><p class="muted">A senha temporária não é exibida novamente nem enviada automaticamente.</p><form id="masterUserForm"><div class="form-grid"><label>Nome completo<input id="masterUserName" autocomplete="name" required></label><label>Email<input id="masterUserEmail" type="email" autocomplete="email" required></label><label>Perfil<select id="masterUserRole">${roles.map(([value,label])=>`<option value="${value}">${label}</option>`).join("")}</select></label><label>Senha temporária<input id="masterUserPassword" type="password" autocomplete="new-password" minlength="12" required></label></div><p id="masterUserError" class="form-error hidden" role="alert" aria-live="assertive"></p><button class="primary" id="masterUserSubmit" type="submit">Criar usuário</button></form></section></div>`;
  $("#backToTenants").onclick=()=>admin(root);
  root.querySelectorAll("[data-reset-user]").forEach(button=>button.onclick=()=>{
   resetUser=data.users.find(user=>user.id===button.dataset.resetUser)||null;
   if(!resetUser)return;
   $("#masterUserName").value=resetUser.fullName;
   $("#masterUserEmail").value=resetUser.email;
   $("#masterUserRole").value=resetUser.role;
   $("#masterUserPassword").value="";
   $("#masterUserMode").textContent=`Redefinir senha de ${resetUser.fullName}`;
   $("#masterUserSubmit").textContent="Redefinir senha temporária";
   $("#masterUserPassword").focus();
  });
  $("#masterUserForm").onsubmit=async event=>{
   event.preventDefault();setFormError("#masterUserError");
   if(resetUser&&!confirm("Redefinir a senha temporária encerrará as sessões atuais deste usuário. Continuar?"))return;
   const payload={fullName:$("#masterUserName").value,email:$("#masterUserEmail").value,role:$("#masterUserRole").value,temporaryPassword:$("#masterUserPassword").value};
   try{
    await api(`/admin/tenants/${tenant.id}/users`,{method:"POST",body:JSON.stringify(payload)});
    $("#masterUserPassword").value="";
    toast(resetUser?"Senha temporária redefinida. Compartilhe-a manualmente.":"Usuário criado. Compartilhe a senha temporária manualmente.");
    await masterTenantUsers(root,tenant);
   }catch(error){setFormError("#masterUserError",error.message);}
  };
 };
 render();
}
async function admin(root){
 if(!state.me.isPlatformAdmin){root.innerHTML='<div class="empty">Sem acesso.</div>';return;}
 const [tenants,audit]=await Promise.all([api("/admin/tenants"),api("/admin/audit?limit=50")]);
 const tenantRows=tenants.tenants||[],logs=audit.logs||[];
 root.innerHTML=`<div class="pagehead"><div><h1>Admin Master</h1><div class="sub">Empresas, acessos assistidos e atividade administrativa da plataforma</div></div><span class="chip">${tenantRows.length} empresa(s)</span></div>${state.me.tenantId?`<div class="notice"><strong>Acesso assistido ativo</strong> · ${escapeHtml(state.me.tenantName||"")} <button id="exitSupport">Sair do acesso assistido</button></div>`:""}<div class="grid two" style="margin-top:12px"><section class="card section"><div class="section-title"><h2>Empresas</h2><span class="chip blue">${tenantRows.length} tenant(s)</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Empresa</th><th>Status</th><th>Usuários</th><th>Ações</th></tr></thead><tbody>${tenantRows.map(tenant=>`<tr><td><strong>${escapeHtml(tenant.name)}</strong><br><small>${escapeHtml(tenant.slug)}</small></td><td><span class="chip ${tenant.status==="active"?"green":"amber"}">${escapeHtml(tenant.status)}</span></td><td>${tenant.users_count}</td><td><button data-manage-users="${tenant.id}">Gerenciar usuários</button> <button data-support="${tenant.id}">Acessar</button></td></tr>`).join("")||'<tr><td colspan="4" class="muted">Nenhuma empresa cadastrada.</td></tr>'}</tbody></table></div></section><section class="card section"><div class="section-title"><h2>Criar tenant</h2><span class="chip amber">Owner obrigatório</span></div><div class="form-grid"><label>Nome<input id="tName"></label><label>Slug<input id="tSlug"></label><label>Nome do owner<input id="tOwner"></label><label>Email do owner<input id="tEmail" type="email"></label><label class="wide">Senha inicial<input id="tPass" type="password" minlength="12"></label></div><button class="primary" id="createTenant">Criar empresa</button></section></div><section class="card section" style="margin-top:12px"><div class="section-title"><h2>Auditoria global</h2><span class="chip">${logs.length} evento(s)</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Data</th><th>Ação</th><th>Ator</th><th>Empresa</th></tr></thead><tbody>${logs.map(event=>`<tr><td>${date(event.created_at)}</td><td><strong>${escapeHtml(event.action)}</strong></td><td>${escapeHtml(event.actor_email||event.actor_type||"Plataforma")}</td><td>${escapeHtml(event.tenant_name||"Plataforma")}</td></tr>`).join("")||'<tr><td colspan="4" class="muted">Sem eventos.</td></tr>'}</tbody></table></div></section>`;
 $("#createTenant").onclick=async()=>{try{await api("/admin/tenants",{method:"POST",body:JSON.stringify({name:$("#tName").value,slug:$("#tSlug").value,ownerName:$("#tOwner").value,ownerEmail:$("#tEmail").value,ownerPassword:$("#tPass").value})});toast("Empresa criada.");admin(root)}catch(error){toast(error.message,true)}};
 root.querySelectorAll("[data-manage-users]").forEach(button=>button.onclick=async()=>{const tenant=tenantRows.find(item=>item.id===button.dataset.manageUsers);if(!tenant)return;try{await masterTenantUsers(root,tenant);}catch(error){toast(error.message,true);}});
 root.querySelectorAll("[data-support]").forEach(button=>button.onclick=async()=>{const reason=prompt("Motivo do acesso assistido:");if(!reason)return;try{const result=await api(`/admin/tenants/${button.dataset.support}/support-session`,{method:"POST",body:JSON.stringify({reason})});state.csrf=result.csrfToken;state.me=(await api("/auth/me")).user;showApp();toast("Acesso assistido iniciado.");await navigate("dashboard")}catch(error){toast(error.message,true)}});
 if($("#exitSupport"))$("#exitSupport").onclick=async()=>{try{const result=await api("/admin/exit-support",{method:"POST",body:"{}"});state.csrf=result.csrfToken;state.me=(await api("/auth/me")).user;showApp();toast("Acesso assistido encerrado.");await navigate("admin")}catch(error){toast(error.message,true)}};
}
async function modulePage(root,key){
 const data=await api(`/${key}`);
 if(key==="products"){
  const products=data.products||[];
  root.innerHTML=`<div class="pagehead"><div><h1>Produtos</h1><div class="sub">Prontuário operacional de custos e estoque por SKU</div></div><button class="primary" id="addProduct">+ Novo produto</button></div><div class="grid kpis"><div class="card kpi"><small>Produtos cadastrados</small><strong>${products.length}</strong></div><div class="card kpi"><small>Custos informados</small><strong>${products.filter(x=>x.cost!=null).length}</strong></div><div class="card kpi"><small>Estoques informados</small><strong>${products.filter(x=>x.stock!=null).length}</strong></div></div><section class="card section"><div class="section-title"><h2>Catálogo</h2><span class="chip">${products.length} SKU(s)</span></div><div class="table-wrap"><table class="table"><thead><tr><th>SKU</th><th>Produto</th><th>Custo</th><th>Estoque</th><th>Atualizado</th></tr></thead><tbody>${products.map(x=>`<tr><td><strong>${escapeHtml(x.sku)}</strong></td><td>${escapeHtml(x.name)}</td><td>${x.cost==null?"—":money(x.cost)}</td><td>${x.stock??"—"}</td><td>${date(x.updated_at)}</td></tr>`).join("")||'<tr><td colspan="5" class="muted">Nenhum produto cadastrado.</td></tr>'}</tbody></table></div></section><div id="moduleForm"></div>`;
  $("#addProduct").onclick=()=>{$("#moduleForm").innerHTML=`<section class="card section" style="margin-top:12px"><h3>Novo produto</h3><div class="form-grid"><label>SKU<input id="pSku"></label><label>Nome<input id="pName"></label><label>Custo<input id="pCost" type="number" step=".01"></label><label>Estoque<input id="pStock" type="number" step=".01"></label></div><button class="primary" id="saveProduct">Salvar</button></section>`;$("#saveProduct").onclick=async()=>{try{await api("/products",{method:"POST",body:JSON.stringify({sku:$("#pSku").value,name:$("#pName").value,cost:$("#pCost").value||null,stock:$("#pStock").value||null})});toast("Produto salvo.");modulePage(root,key)}catch(e){toast(e.message,true)}}};return;
 }
 if(key==="profit"){
  const snapshots=data.snapshots||[],hasSnapshots=snapshots.length>0,realizedSnapshots=snapshots.filter(x=>x.calculation_type==="realized"),realizedFees=realizedSnapshots.reduce((sum,x)=>sum+Number(x.fees_amount||0),0);
  root.innerHTML=`<div class="pagehead"><div><h1>Profit</h1><div class="sub">Margem esperada e realizada com origem financeira rastreável</div></div><span class="chip ${hasSnapshots?"green":"amber"}">${hasSnapshots?`${snapshots.length} cálculo(s)`:"Sem cálculos"}</span></div><div class="grid kpis"><div class="card kpi"><small>Venda bruta</small><strong>${hasSnapshots?money(data.totals?.gross_amount):"—"}</strong></div><div class="card kpi"><small>Taxas reais</small><strong>${realizedSnapshots.length?money(realizedFees):"—"}</strong></div><div class="card kpi"><small>Contribuição</small><strong>${hasSnapshots?money(data.totals?.contribution_amount):"—"}</strong></div></div><section class="card section"><div class="section-title"><h2>Margem por pedido</h2><span class="muted">Calcule ou atualize em Pedidos</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Data</th><th>Pedido</th><th>Tipo</th><th>Bruto</th><th>Taxas</th><th>Custos</th><th>MC</th></tr></thead><tbody>${snapshots.map(x=>`<tr><td>${date(x.calculated_at)}</td><td>${escapeHtml(x.source_order_id||"—")}</td><td><span class="chip ${x.calculation_type==="realized"?"green":"blue"}">${x.calculation_type==="realized"?"Realizada":"Esperada"}</span></td><td>${money(x.gross_amount)}</td><td>${money(x.fees_amount)}</td><td>${money(Number(x.shipping_amount||0)+Number(x.ads_amount||0)+Number(x.tax_amount||0)+Number(x.cost_amount||0))}</td><td><strong>${money(x.contribution_amount)}</strong></td></tr>`).join("")||'<tr><td colspan="7" class="muted">Nenhum cálculo registrado. Use Pedidos para buscar taxas reais e calcular depois.</td></tr>'}</tbody></table></div></section>`;return;
 }
 if(key==="pricing"){
  root.innerHTML=`<div class="pagehead"><div><h1>Pricing</h1><div class="sub">Simulação econômica manual antes de qualquer decisão</div></div></div><div class="banner-ai"><h4>Simulação sem publicação</h4><p>O simulador compara contribuição total, não apenas margem por unidade. A tabela informativa de Comissões não entra neste cálculo.</p></div><div class="price-sim" style="margin-top:12px"><section class="card section"><h3>Simulação econômica</h3><div class="form-grid"><label>Preço atual<input id="prCurrent" type="number" step=".01"></label><label>Preço candidato<input id="prCandidate" type="number" step=".01"></label><label>Custo unitário<input id="prCost" type="number" step=".01"></label><label>Unidades atuais<input id="prUnits" type="number"></label><label>Unidades projetadas<input id="prProjected" type="number"></label></div><button class="primary" id="simulatePrice">Simular</button><div id="simulationResult" aria-live="polite"></div></section><section class="card section"><h3>Decisões salvas</h3><p class="muted">${(data.decisions||[]).length} decisão(ões) registrada(s).</p>${(data.decisions||[]).slice(0,10).map(x=>`<div class="metric-row"><strong>${escapeHtml(x.sku||x.name||"Produto")}</strong><span>${escapeHtml(x.recommendation||x.status||"—")}</span></div>`).join("")||'<p class="muted">Nenhuma decisão registrada.</p>'}</section></div>`;$("#simulatePrice").onclick=async()=>{try{const d=await api("/pricing/simulate",{method:"POST",body:JSON.stringify({currentPrice:$("#prCurrent").value,candidatePrice:$("#prCandidate").value,unitCost:$("#prCost").value,currentUnits:$("#prUnits").value,projectedUnits:$("#prProjected").value})});const x=d.simulation;$("#simulationResult").innerHTML=`<div class="notice" style="margin-top:12px">Atual: <strong>${money(x.currentContribution)}</strong> · Candidato: <strong>${money(x.candidateContribution)}</strong> · Delta: <strong>${money(x.delta)}</strong> · ${escapeHtml(x.recommendation)}</div>`}catch(e){toast(e.message,true)}};return;
 }
 if(key==="market"){
  root.innerHTML=`<div class="pagehead"><div><h1>Market</h1><div class="sub">Observações competitivas e posicionamento por produto</div></div></div><section class="card section"><div class="section-title"><h2>Observações de mercado</h2><span class="chip">${(data.observations||[]).length} registro(s)</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Data</th><th>Produto</th><th>Canal</th><th>Concorrente</th><th>Preço</th></tr></thead><tbody>${(data.observations||[]).map(x=>`<tr><td>${date(x.observed_at)}</td><td>${escapeHtml(x.sku||x.name||"—")}</td><td>${escapeHtml(x.channel||"—")}</td><td>${escapeHtml(x.competitor||"—")}</td><td>${x.observed_price==null?"—":money(x.observed_price)}</td></tr>`).join("")||'<tr><td colspan="5" class="muted">Sem observações. A estrutura está pronta para o futuro conector de concorrência.</td></tr>'}</tbody></table></div></section>`;return;
 }
 if(key==="ads"){
  const totals=data.totals||{},metrics=data.metrics||[],sources=data.sources||[];
  root.innerHTML=`<div class="pagehead"><div><h1>Ads</h1><div class="sub">Investimento, rentabilidade e margem pós-mídia</div></div><span class="chip ${metrics.length?"green":"amber"}">${metrics.length?`${metrics.length} métrica(s)`:"Sem métricas"}</span></div><div class="grid kpis"><div class="card kpi"><small>Investimento</small><strong>${totals.spend==null?"—":money(totals.spend)}</strong></div><div class="card kpi"><small>Receita atribuída</small><strong>${totals.attributedRevenue==null&&totals.revenue==null?"—":money(totals.attributedRevenue??totals.revenue)}</strong></div><div class="card kpi"><small>ROAS</small><strong>${totals.roas==null?"—":Number(totals.roas).toFixed(2)}</strong></div><div class="card kpi"><small>Fontes</small><strong>${sources.length}</strong></div></div><div class="toolbar"><span class="chip blue">Dados importados</span><span class="muted">Ações de fonte e importação estão disponíveis no workspace abaixo.</span></div><section class="card section"><div class="section-title"><h2>Campanhas e métricas</h2><span class="chip">${metrics.length}</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Data</th><th>Canal</th><th>Spend</th><th>Receita</th><th>Pedidos</th></tr></thead><tbody>${metrics.map(x=>`<tr><td>${escapeHtml(x.metric_date)}</td><td>${escapeHtml(x.channel)}</td><td>${money(x.spend)}</td><td>${money(x.attributed_revenue??x.revenue)}</td><td>${x.attributed_orders??x.orders??0}</td></tr>`).join("")||'<tr><td colspan="5" class="muted">Sem métricas de Ads importadas.</td></tr>'}</tbody></table></div></section>`;return;
 }
 if(key==="cash"){
  const summary=data.summary||{},entries=data.entries||[],projection=summary.scenarios?.base||[];
  root.innerHTML=`<div class="pagehead"><div><h1>Cash</h1><div class="sub">Fluxo de caixa, recebíveis e compromissos financeiros</div></div><span class="chip ${summary.overdueCount?"red":"green"}">${summary.overdueCount?`${summary.overdueCount} vencido(s)`:"Sem vencidos"}</span></div><div class="grid kpis"><div class="card kpi"><small>Caixa atual</small><strong>${summary.currentBalance==null?"—":money(summary.currentBalance)}</strong></div><div class="card kpi"><small>Comprometido</small><strong>${summary.committed==null?"—":money(summary.committed)}</strong></div><div class="card kpi"><small>Caixa livre</small><strong>${summary.freeCash==null?"—":money(summary.freeCash)}</strong></div><div class="card kpi"><small>A receber</small><strong>${summary.receivable==null?"—":money(summary.receivable)}</strong></div></div><div class="toolbar"><button class="primary" id="cashNew">+ Movimento</button><span class="muted">Entradas ${money(summary.inflow)} · Saídas ${money(summary.outflow)}</span></div><div class="grid two"><section class="card section"><div class="section-title"><h2>Projeção de caixa</h2><span class="chip">Cenário base</span></div>${projection.map(point=>`<div class="scenario metric-row"><span>D+${point.days}</span><strong>${money(point.balance)}</strong></div>`).join("")||'<p class="muted">Cadastre movimentos com vencimento para projetar o caixa.</p>'}</section><section class="card section"><div class="section-title"><h2>Compromissos</h2></div><div class="metric-row"><span>Saldo atual</span><strong>${summary.currentBalance==null?"—":money(summary.currentBalance)}</strong></div><div class="metric-row"><span>Obrigações pendentes</span><strong>${summary.committed==null?"—":money(summary.committed)}</strong></div><div class="metric-row"><span>Caixa realmente livre</span><strong>${summary.freeCash==null?"—":money(summary.freeCash)}</strong></div></section></div><section class="card section" style="margin-top:12px"><div class="section-title"><h2>Movimentos</h2><span class="chip">${entries.length}</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Vencimento</th><th>Tipo</th><th>Descrição</th><th>Status</th><th>Valor</th></tr></thead><tbody>${entries.map(x=>`<tr><td>${escapeHtml(x.expected_date||x.due_date||"—")}</td><td>${escapeHtml(x.entry_type)}</td><td>${escapeHtml(x.description||"—")}</td><td><span class="chip ${x.status==="paid"?"green":x.status==="cancelled"?"red":"amber"}">${escapeHtml(x.status)}</span></td><td>${money(x.amount)}</td></tr>`).join("")||'<tr><td colspan="5" class="muted">Sem movimentos financeiros.</td></tr>'}</tbody></table></div></section><div id="cashForm"></div>`;$("#cashNew").onclick=()=>{$("#cashForm").innerHTML=`<div class="card"><div class="form-grid"><label>Tipo<input id="cashType" placeholder="inflow / payable"></label><label>Valor<input id="cashAmount" type="number" step=".01"></label><label>Vencimento<input id="cashDue" type="date"></label><label>Descrição<input id="cashDesc"></label></div><button id="cashSave" class="primary">Salvar</button></div>`;$("#cashSave").onclick=async()=>{try{await api("/cash",{method:"POST",body:JSON.stringify({entryType:$("#cashType").value,amount:$("#cashAmount").value,dueDate:$("#cashDue").value||null,description:$("#cashDesc").value})});toast("Movimento salvo.");modulePage(root,key)}catch(e){toast(e.message,true)}}};return;
 }
 if(key==="audit"){
  const cases=data.cases||[],logs=data.logs||[],severityClass=value=>value==="critical"?"red":["high","medium"].includes(value)?"amber":"blue",openCases=cases.filter(x=>!["resolved","closed"].includes(x.status));
  root.innerHTML=`<div class="pagehead"><div><h1>Audit</h1><div class="sub">Conciliação e divergências operacionais</div></div><span class="chip ${openCases.length?"red":"green"}">${openCases.length} caso(s) aberto(s)</span></div><div class="grid kpis"><div class="card kpi"><small>Casos encontrados</small><strong>${cases.length}</strong></div><div class="card kpi"><small>Críticos</small><strong>${cases.filter(x=>x.severity==="critical").length}</strong></div><div class="card kpi"><small>Em análise</small><strong>${openCases.length}</strong></div><div class="card kpi"><small>Eventos de segurança</small><strong>${logs.length}</strong></div></div><section class="card section"><div class="section-title"><h2>Casos e próxima ação</h2><span class="chip">${cases.length}</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Caso</th><th>Origem</th><th>Pedido</th><th>Severidade</th><th>Status</th><th>Criado</th><th>Próxima ação</th></tr></thead><tbody>${cases.map(x=>`<tr><td><strong>${escapeHtml(x.title)}</strong></td><td>${escapeHtml(x.source_channel||"—")}</td><td>${escapeHtml(x.source_order_id||"—")}</td><td><span class="chip ${severityClass(x.severity)}">${escapeHtml(x.severity||"não informada")}</span></td><td><span class="chip">${escapeHtml(x.status)}</span></td><td>${date(x.created_at)}</td><td>${["resolved","closed"].includes(x.status)?"Encerrado":"Analisar evidências"}</td></tr>`).join("")||'<tr><td colspan="7" class="muted">Nenhuma divergência registrada.</td></tr>'}</tbody></table></div></section><section class="card section" style="margin-top:12px"><div class="section-title"><h2>Log de segurança</h2><span class="chip blue">${logs.length}</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Data</th><th>Ação</th><th>Recurso</th><th>Ator</th></tr></thead><tbody>${logs.slice(0,30).map(x=>`<tr><td>${date(x.created_at)}</td><td>${escapeHtml(x.action)}</td><td>${escapeHtml(x.resource_type||"—")} ${escapeHtml(x.resource_id||"")}</td><td>${escapeHtml(x.actor_type||"—")}</td></tr>`).join("")||'<tr><td colspan="4" class="muted">Sem eventos.</td></tr>'}</tbody></table></div></section>`;return;
 }
 if(key==="actions"){
  const actions=data.actions||[],evaluated=actions.filter(x=>x.evaluated_at||x.status==="evaluated");
  root.innerHTML=`<div class="pagehead"><div><h1>Actions</h1><div class="sub">Histórico de decisões e resultados observados</div></div><span class="chip ${actions.length?"green":"amber"}">${actions.length} ação(ões)</span></div><div class="grid kpis"><div class="card kpi"><small>Ações registradas</small><strong>${actions.length}</strong></div><div class="card kpi"><small>Avaliadas</small><strong>${evaluated.length}</strong></div><div class="card kpi"><small>Planejadas</small><strong>${actions.filter(x=>x.status==="planned").length}</strong></div><div class="card kpi"><small>Em monitoramento</small><strong>${actions.filter(x=>["monitoring","in_progress"].includes(x.status)).length}</strong></div></div><div class="toolbar"><button class="primary" id="actionNew">+ Registrar ação</button></div><section class="card section"><div class="section-title"><h2>Linha do tempo de ações</h2><span class="chip">Últimas ${Math.min(actions.length,8)}</span></div><div class="timeline"><div class="stack">${actions.slice(0,8).map(x=>`<div class="tl card"><small>${date(x.created_at)}</small><strong>${escapeHtml(x.action_type)}</strong><span class="chip ${x.status==="evaluated"?"green":"blue"}">${escapeHtml(x.status)}</span><span>${escapeHtml(x.reason||"Sem motivo informado")}</span></div>`).join("")||'<p class="muted">Nenhuma ação registrada para compor a linha do tempo.</p>'}</div></div></section><section class="card section" style="margin-top:12px"><div class="section-title"><h2>Registro detalhado</h2><span class="chip">${actions.length}</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Data</th><th>Tipo</th><th>Status</th><th>Motivo</th><th>Avaliada</th></tr></thead><tbody>${actions.map(x=>`<tr><td>${date(x.created_at)}</td><td><strong>${escapeHtml(x.action_type)}</strong></td><td><span class="chip ${x.status==="evaluated"?"green":"blue"}">${escapeHtml(x.status)}</span></td><td>${escapeHtml(x.reason||"—")}</td><td>${date(x.evaluated_at)}</td></tr>`).join("")||'<tr><td colspan="5" class="muted">Nenhuma ação registrada.</td></tr>'}</tbody></table></div></section><div id="actionForm"></div>`;$("#actionNew").onclick=()=>{$("#actionForm").innerHTML=`<div class="card"><div class="form-grid"><label>Tipo<input id="aType"></label><label>Status<input id="aStatus" value="planned"></label><label class="wide">Motivo<textarea id="aReason"></textarea></label></div><button class="primary" id="aSave">Salvar</button></div>`;$("#aSave").onclick=async()=>{try{await api("/actions",{method:"POST",body:JSON.stringify({actionType:$("#aType").value,status:$("#aStatus").value,reason:$("#aReason").value})});toast("Ação registrada.");modulePage(root,key)}catch(e){toast(e.message,true)}}};return;
 }
 if(key==="reports"){
  const monthlyOrders=data.monthlyOrders||[],monthlyProfit=data.monthlyProfit||[],feeLookups=data.feeLookups||[],reportMonths=[...new Set([...monthlyOrders.map(x=>String(x.month)),...monthlyProfit.map(x=>String(x.month))])].sort().reverse().slice(0,12),currentMonth=reportMonths[0],previousMonth=reportMonths[1],currentOrders=monthlyOrders.find(x=>String(x.month)===currentMonth),previousOrders=monthlyOrders.find(x=>String(x.month)===previousMonth),currentProfit=monthlyProfit.find(x=>String(x.month)===currentMonth),previousProfit=monthlyProfit.find(x=>String(x.month)===previousMonth);
  root.innerHTML=`<div class="pagehead"><div><h1>Reports & Forecast</h1><div class="sub">Relatórios comparativos com histórico financeiro real</div></div><span class="chip ${reportMonths.length?"green":"amber"}">${reportMonths.length?`${reportMonths.length} período(s)`:"Sem histórico"}</span></div><div class="toolbar"><span class="chip blue">Período atual</span><span>${escapeHtml(currentOrders?.month||currentProfit?.month||"não disponível")}</span><strong>vs</strong><span class="chip">Período anterior</span><span>${escapeHtml(previousOrders?.month||previousProfit?.month||"não disponível")}</span></div><div class="grid kpis"><div class="card kpi"><small>Produtos</small><strong>${data.productCount??0}</strong></div><div class="card kpi"><small>Receita do período</small><strong>${currentOrders?money(currentOrders.revenue):"—"}</strong></div><div class="card kpi"><small>MC do período</small><strong>${currentProfit?money(currentProfit.contribution):"—"}</strong></div><div class="card kpi"><small>Consultas de taxas</small><strong>${feeLookups.reduce((a,x)=>a+Number(x.lookups||0),0)}</strong></div></div><div class="grid two"><section class="card section"><div class="section-title"><h2>Comparação e cenários</h2></div><div class="scenarios"><div class="scenario metric-row"><span>Atual · ${escapeHtml(currentOrders?.month||currentProfit?.month||"sem período")}</span><span>${currentOrders?`${currentOrders.orders} pedido(s) · ${money(currentOrders.revenue)}`:"Sem pedidos"}</span><strong>${currentProfit?`MC ${money(currentProfit.contribution)}`:"Sem snapshot de Profit"}</strong></div><div class="scenario metric-row"><span>Anterior · ${escapeHtml(previousOrders?.month||previousProfit?.month||"sem período")}</span><span>${previousOrders?`${previousOrders.orders} pedido(s) · ${money(previousOrders.revenue)}`:"Sem pedidos"}</span><strong>${previousProfit?`MC ${money(previousProfit.contribution)}`:"Sem snapshot de Profit"}</strong></div><div class="scenario metric-row"><span>Forecast</span><strong class="muted">Sem série de forecast disponível na API atual.</strong></div></div></section><section class="card section"><div class="section-title"><h2>Ações por status</h2><span class="chip">${(data.actionsByStatus||[]).reduce((sum,x)=>sum+Number(x.count||0),0)}</span></div>${(data.actionsByStatus||[]).map(x=>`<div class="metric-row"><span><span class="chip">${escapeHtml(x.status)}</span></span><strong>${x.count}</strong></div>`).join("")||'<p class="muted">Nenhuma ação registrada no período.</p>'}</section></div><section class="card section" style="margin-top:12px"><div class="section-title"><h2>Histórico mensal</h2><span class="chip">${reportMonths.length}</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Mês</th><th>Pedidos</th><th>Receita</th><th>Venda bruta</th><th>Contribuição</th></tr></thead><tbody>${reportMonths.map(month=>{const orders=monthlyOrders.find(x=>String(x.month)===month),profit=monthlyProfit.find(x=>String(x.month)===month);return `<tr><td>${escapeHtml(month)}</td><td>${orders?.orders??"—"}</td><td>${orders?money(orders.revenue):"—"}</td><td>${profit?money(profit.gross):"—"}</td><td>${profit?money(profit.contribution):"—"}</td></tr>`}).join("")||'<tr><td colspan="5" class="muted">Sem histórico mensal para comparar.</td></tr>'}</tbody></table></div></section>`;return;
 }
 root.innerHTML='<div class="empty">Módulo disponível.</div>';
}
$("#loginForm").addEventListener("submit",async e=>{e.preventDefault();setFormError("#loginError");const email=$("#loginEmail").value;const password=$("#loginPassword").value;try{const d=await api("/auth/login",{method:"POST",body:JSON.stringify({email,password})});state.csrf=d.csrfToken;state.me=d.user;if(state.me.passwordChangeRequired)return showFirstAccess();showApp();navigate(state.me.isPlatformAdmin?"admin":"dashboard")}catch(e){setFormError("#loginError",e.message)}});$("#passwordChangeForm").addEventListener("submit",async e=>{e.preventDefault();setFormError("#passwordChangeError");const currentPassword=$("#currentPassword").value;const newPassword=$("#newPassword").value;const confirmPassword=$("#confirmPassword").value;if(newPassword!==confirmPassword)return setFormError("#passwordChangeError","A confirmação da nova senha não corresponde.");try{const d=await api("/auth/change-password",{method:"POST",body:JSON.stringify({currentPassword,newPassword})});state.csrf=d.csrfToken;state.me=d.user;$("#passwordChangeForm").reset();showApp();navigate(state.me.isPlatformAdmin?"admin":"dashboard")}catch(e){setFormError("#passwordChangeError",e.message)}});$("#logoutBtn").onclick=async()=>{try{await api("/auth/logout",{method:"POST",body:"{}"})}catch{}state.me=null;state.csrf=null;showLogin()};$("#refreshPage").onclick=()=>render();window.addEventListener("popstate",()=>{const p=location.pathname.split("/").pop();state.page=p||"dashboard";renderNav();render()});boot();
